<?php
/** Plugin Name: TEMP PS S1672 feeds v2.4.1 deploy */
add_action('wp_loaded', function(){
  if (!isset($_GET['ps_s1672d'])) return; $f=$_GET['ps_s1672d'];
  header('Content-Type: application/json; charset=utf-8'); $o=array('v'=>'S1672d','faze'=>$f);
  $path = WP_PLUGIN_DIR.'/petshop-feeds/petshop-feeds.php'; $bak = wp_upload_dir()['basedir'].'/ps-backups/petshop-feeds.php.bak_s1672';
  try {
    if ($f==='D') {
      $o['md5_pries']=md5_file($path); if($o['md5_pries']!=='ecd8a18cd6dd89b6bf1121b02e53386d') throw new Exception('gyvas ne v2.4.0');
      $src = gzdecode(base64_decode('')); $o['md5_naujas']=md5($src);
      if ($o['md5_naujas']!=='a5d344e6425b1bb2a512b1fac057ffcd') throw new Exception('md5 nesutampa');
      $tok = token_get_all($src, TOKEN_PARSE); $o['tokenu']=count($tok);
      if (!copy($path,$bak)) throw new Exception('backup nepavyko'); $o['bak_md5']=md5_file($bak);
      $o['irasyta']=file_put_contents($path,$src); if(function_exists('opcache_invalidate')) opcache_invalidate($path,true);
      $o['md5_po']=md5_file($path);
      $h=wp_remote_get(home_url('/?ps_hb=1&r='.wp_rand()),array('timeout'=>25,'sslverify'=>false)); $hc=is_wp_error($h)?0:wp_remote_retrieve_response_code($h); $o['heartbeat']=$hc;
      if ($hc>=500 || $hc===0) { copy($bak,$path); $o['ROLLBACK']=md5_file($path); }
    } elseif ($f==='G') {
      $o['versija']=defined('PS_FEEDS_VERSIJA')?PS_FEEDS_VERSIJA:'?'; $o['fn']=function_exists('ps_feeds_google_svoris');
      $o['bak_google']=copy(ps_feeds_kelias('google'), wp_upload_dir()['basedir'].'/ps-backups/google.xml.bak_s1672');
      $st=ps_feeds_generuoti(array('google'), false); unset($st['pvz']); $o['st']=$st;
    } elseif ($f==='V') {
      $file=ps_feeds_kelias('google'); $o['baitai']=filesize($file); $o['mtime']=date('Y-m-d H:i:s',filemtime($file));
      libxml_use_internal_errors(true); $x=simplexml_load_file($file); if(!$x){ $o['xml_klaida']=array_map(function($e){return trim($e->message);},array_slice(libxml_get_errors(),0,3)); echo json_encode($o); exit; }
      $ns=$x->getNamespaces(true); $c=array('items'=>0,'su_svoriu'=>0,'be_svorio'=>0,'sv_0_5'=>0,'in_stock'=>0,'out_of_stock'=>0); $pvz=array(); $tikr=array('16178','15417','14215','25163','14280');
      foreach($x->channel->item as $it){ $g=$it->children($ns['g']); $c['items']++; $sw=(string)$g->shipping_weight; if($sw==='') $c['be_svorio']++; else { $c['su_svoriu']++; if($sw==='0.5 kg') $c['sv_0_5']++; } $av=(string)$g->availability; $c[$av]=($c[$av]??0)+1;
        if(in_array((string)$g->id,$tikr,true)) $pvz[]=array((string)$g->id,(string)$it->title,$sw); }
      $o['c']=$c; $o['pvz']=$pvz;
      $h=wp_remote_get(home_url('/feed/kaina24/'),array('timeout'=>25,'sslverify'=>false,'method'=>'HEAD')); $o['kaina24_http']=is_wp_error($h)?'err':wp_remote_retrieve_response_code($h);
      $h=wp_remote_get(home_url('/feed/google/'),array('timeout'=>25,'sslverify'=>false,'method'=>'HEAD')); $o['google_http']=is_wp_error($h)?'err':wp_remote_retrieve_response_code($h);
      $o['md5_gyvas']=md5_file($path);
    }
  } catch (Throwable $e) { $o['FATAL']=$e->getMessage().' @'.$e->getLine(); if($f==='D' && file_exists($bak) && md5_file($path)!==md5_file($bak)) { copy($bak,$path); $o['ROLLBACK']=1; } }
  echo json_encode($o, JSON_UNESCAPED_UNICODE); exit;
});
